'use server'

import { refresh } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from './lib/preferences'

// Replace with the authenticated user's ID from your session.
const CURRENT_USER_ID = 'demo-user'

export async function toggleNotifications() {
  const current = await getNotificationPreference(CURRENT_USER_ID)
  await setNotificationPreference(CURRENT_USER_ID, !current)

  // Refresh the client router so the current page re-renders with the new value.
  refresh()
}

