import { connection } from 'next/server'
import { toggleNotifications } from './actions'
import {
  getCurrentUserId,
  getNotificationPreference,
} from './lib/preferences'

export default async function Home() {
  // Render per request so the page reflects the latest preference.
  await connection()
  const enabled = await getNotificationPreference(await getCurrentUserId())

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

